class Solution {
    public boolean uniqueOccurrences(int[] arr){
        Map<Integer,Integer> frequency=new HashMap<>();
        for(int value:arr)frequency.merge(value,1,Integer::sum);
        Set<Integer> seen=new HashSet<>();
        for(int count:frequency.values())if(!seen.add(count))return false;
        return true;
    }
}

code.kotlin:
class Solution {
    fun uniqueOccurrences(arr:IntArray):Boolean{
        val frequency=mutableMapOf<Int,Int>();
        for(value in arr)frequency[value]=(frequency[value]?:0)+1;
        val seen=mutableSetOf<Int>();
        return frequency.values.all{
            seen.add(it)
        }
    }
}

code.cpp:
class Solution {
    public: bool uniqueOccurrences(vector<int>& arr){
        unordered_map<int,int> frequency;
        for(int value:arr)++frequency[value];
        unordered_set<int> seen;
        for(auto [value,count]:frequency)if(!seen.insert(count).second)return false;
        return true;
    }
};
